SELECT 100.0 * (
  (SELECT COALESCE(SUM(amount_units), 0) FROM observations WHERE period = 'P2') -
  (SELECT COALESCE(SUM(amount_units), 0) FROM observations WHERE period = 'P1')
) / (CAST((SELECT COALESCE(SUM(amount_units), 0) FROM observations WHERE period = 'P1') AS REAL)) AS value;

SELECT 100.0 * (
  (SELECT COALESCE(SUM(o2.amount_units), 0) FROM observations o2 WHERE o2.period = 'P2' AND o2.network_asset IN (SELECT network_asset FROM observations WHERE period = 'P1')) -
  (SELECT COALESCE(SUM(o1.amount_units), 0) FROM observations o1 WHERE o1.period = 'P1')
) / (CAST((SELECT COALESCE(SUM(amount_units), 0) FROM observations WHERE period = 'P1') AS REAL)) AS value;
